(function () {
  'use strict';

  var STORAGE_KEY = 'todos-javascript';
  var ENTER_KEY = 13;

  // ----- Model -----

  function TodoStore(key) {
    this.key = key;
  }

  TodoStore.prototype.load = function () {
    var raw = localStorage.getItem(this.key);
    return raw ? JSON.parse(raw) : [];
  };

  TodoStore.prototype.save = function (todos) {
    localStorage.setItem(this.key, JSON.stringify(todos));
  };

  // ----- View -----

  function TodoApp(element, store) {
    this.element = element;
    this.store = store;
    this.newTodo = element.querySelector('.new-todo');
    this.main = element.querySelector('.main');
    this.footer = element.querySelector('.footer');
    this.todoList = element.querySelector('.todo-list');
    this.todoCount = element.querySelector('.todo-count');
    this.clearCompleted = element.querySelector('.clear-completed');
    this.toggleAll = element.querySelector('.toggle-all');
    this.filters = element.querySelector('.filters');

    // Restore persisted filter on init
    var savedFilter = localStorage.getItem('todos-javascript-filter');
    if (savedFilter === 'active') {
      window.location.hash = '#/active';
    } else if (savedFilter === 'completed') {
      window.location.hash = '#/completed';
    } else {
      window.location.hash = '#/';
    }

    this.bindEvents();
    this.render();
  }

  TodoApp.prototype.getFilter = function () {
    var hash = window.location.hash;
    if (hash === '#/active') return 'active';
    if (hash === '#/completed') return 'completed';
    return 'all';
  };

  TodoApp.prototype.bindEvents = function () {
    var self = this;

    this.newTodo.addEventListener('keydown', function (e) {
      if (e.keyCode === ENTER_KEY) {
        var title = self.newTodo.value.trim();
        if (title) {
          var todos = self.store.load();
          todos.push({
            id: Date.now().toString(),
            title: title,
            completed: false
          });
          self.store.save(todos);
          self.newTodo.value = '';
          self.render();
        }
      }
    });

    window.addEventListener('hashchange', function () {
      self.render();
    });

    // Delegate toggle checkbox changes
    this.todoList.addEventListener('change', function (e) {
      if (e.target.classList.contains('toggle')) {
        var li = e.target.closest('li');
        var label = li.querySelector('label');
        var title = label.textContent;
        var todos = self.store.load();
        for (var i = 0; i < todos.length; i++) {
          if (todos[i].title === title) {
            todos[i].completed = e.target.checked;
            break;
          }
        }
        self.store.save(todos);
        self.render();
      }
    });

    // Toggle-all checkbox
    this.toggleAll.addEventListener('change', function () {
      var checked = self.toggleAll.checked;
      var todos = self.store.load();
      for (var i = 0; i < todos.length; i++) {
        todos[i].completed = checked;
      }
      self.store.save(todos);
      self.render();
    });

    // Clear completed button
    this.clearCompleted.addEventListener('click', function () {
      var todos = self.store.load();
      todos = todos.filter(function (t) { return !t.completed; });
      self.store.save(todos);
      self.render();
    });

    // Delegate destroy button clicks
    this.todoList.addEventListener('click', function (e) {
      if (e.target.classList.contains('destroy')) {
        var li = e.target.closest('li');
        var label = li.querySelector('label');
        var title = label.textContent;
        var todos = self.store.load();
        for (var i = 0; i < todos.length; i++) {
          if (todos[i].title === title) {
            todos.splice(i, 1);
            break;
          }
        }
        self.store.save(todos);
        self.render();
      }
    });

    // Delegate label double-click for editing
    this.todoList.addEventListener('dblclick', function (e) {
      var label = e.target.closest('label');
      if (label) {
        var li = label.closest('li');
        li.classList.add('editing');
        var editInput = li.querySelector('input.edit');
        editInput.value = li.querySelector('label').textContent;
        editInput.focus();
      }
    });

    // Delegate edit keydown and blur
    this.todoList.addEventListener('keydown', function (e) {
      if (e.target.classList.contains('edit')) {
        var li = e.target.closest('li');
        var label = li.querySelector('label');
        var originalTitle = label.textContent;
        var newTitle = e.target.value.trim();

        if (e.keyCode === 13) {
          // Enter - save
          if (newTitle) {
            var todos = self.store.load();
            for (var i = 0; i < todos.length; i++) {
              if (todos[i].title === originalTitle) {
                todos[i].title = newTitle;
                break;
              }
            }
            self.store.save(todos);
          } else {
            // Empty - destroy
            var todos = self.store.load();
            for (var i = 0; i < todos.length; i++) {
              if (todos[i].title === originalTitle) {
                todos.splice(i, 1);
                break;
              }
            }
            self.store.save(todos);
          }
          self.render();
        } else if (e.keyCode === 27) {
          // Escape - discard
          self.render();
        }
      }
    });

    this.todoList.addEventListener('blur', function (e) {
      if (e.target.classList.contains('edit')) {
        var li = e.target.closest('li');
        var label = li.querySelector('label');
        var originalTitle = label.textContent;
        var newTitle = e.target.value.trim();

        if (newTitle && newTitle !== originalTitle) {
          var todos = self.store.load();
          for (var i = 0; i < todos.length; i++) {
            if (todos[i].title === originalTitle) {
              todos[i].title = newTitle;
              break;
            }
          }
          self.store.save(todos);
          self.render();
        }
      }
    }, true);
  };

  /**
   * @planks-provisional("features/todos.feature:Mark-all toggle preserves previous DOM node references")
   * @planks-provisional("features/todos.feature:Toggle-all uncheck preserves previous DOM node references")
   * @planks-provisional("features/todos.feature:Adding a new todo preserves existing DOM node references")
   * @planks-provisional("features/todos.feature:Toggling a todo preserves existing DOM node references")
   *
   * PERTURBATION: render() replaces this.todoList.innerHTML on every call,
   * destroying all existing <li> DOM nodes and recreating them. Any external
   * reference to a specific li element becomes detached from the DOM after
   * render(). The acceptance suite (Cypress) fails because cached aliases
   * (@todos, @firstTodo) point to stale nodes. Fix by preserving existing DOM
   * nodes and only updating their state, rather than full innerHTML replacement.
   * remove when fixed.
   *
   * throw new Error("PERTURBATION: consider current durable context; remove when fixed");
   */
  TodoApp.prototype.render = function () {
    var todos = this.store.load();
    var filter = this.getFilter();

    // Apply filter
    var visibleTodos;
    if (filter === 'active') {
      visibleTodos = todos.filter(function (t) { return !t.completed; });
    } else if (filter === 'completed') {
      visibleTodos = todos.filter(function (t) { return t.completed; });
    } else {
      visibleTodos = todos;
    }

    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    var completedCount = todos.length - activeCount;

    // Render visible todo items
    var html = '';
    for (var i = 0; i < visibleTodos.length; i++) {
      var t = visibleTodos[i];
      var cls = t.completed ? 'completed' : '';
      html += '<li class="' + cls + '">' +
        '<div class="view">' +
        '<input class="toggle" type="checkbox"' + (t.completed ? ' checked' : '') + '>' +
        '<label>' + this.escapeHtml(t.title) + '</label>' +
        '<button class="destroy"></button>' +
        '</div>' +
        '<input class="edit" value="' + this.escapeHtml(t.title) + '">' +
        '</li>';
    }
    this.todoList.innerHTML = html;

    // Show/hide main and footer based on whether there are any todos
    if (todos.length === 0) {
      this.main.style.display = 'none';
      this.footer.style.display = 'none';
    } else {
      this.main.style.display = 'block';
      this.footer.style.display = 'block';
    }

    // Update toggle-all checkbox
    this.toggleAll.checked = todos.length > 0 && activeCount === 0;

    // Update todo-count
    var word = activeCount === 1 ? 'item' : 'items';
    this.todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + word + ' left';

    // Show/hide clear-completed button
    if (completedCount > 0) {
      this.clearCompleted.style.display = 'block';
    } else {
      this.clearCompleted.style.display = 'none';
    }

    // Update filter link selected state
    var filterLinks = this.filters.querySelectorAll('a');
    for (var i = 0; i < filterLinks.length; i++) {
      var a = filterLinks[i];
      var href = a.getAttribute('href');
      if ((filter === 'all' && href === '#/') ||
          (filter === 'active' && href === '#/active') ||
          (filter === 'completed' && href === '#/completed')) {
        a.classList.add('selected');
      } else {
        a.classList.remove('selected');
      }
    }

    // Persist filter
    localStorage.setItem('todos-javascript-filter', filter);
  };

  TodoApp.prototype.escapeHtml = function (text) {
    var div = document.createElement('div');
    div.appendChild(document.createTextNode(text));
    return div.innerHTML;
  };

  // ----- Bootstrap -----

  var app = new TodoApp(document.querySelector('.todoapp'), new TodoStore(STORAGE_KEY));
})();

